      SUBROUTINE UPDATECC     RESETS FLAGS SO THAT ACCUMULATION OF THE R1 TRANSFER MATRIXC     WILL BEGIN ANEWCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'C      IF (NORD3 .GE. 1) CALL UPSIG      PSIXO = 0.0      PSIYO = 0.0      RCP = .FALSE.      R2P = .FALSE.      R3P = .FALSE.      OCP(2) = .FALSE.      OCP(3) = .FALSE.      IF (NV1 .GE. 1) THEN        DO 100 N = 1, NV1        RVP(N) = .FALSE.        R2VP(N) = .FALSE.  100   CONTINUE      ENDIF      RETURN      END